'use strict';
navs.ai='ChatGPT';navGroups[0][1].push('ai');paths.ai=paths.prompts;
db.aiJobs??=[];
let bridgeStatus={connected:false},bridgeChecking=false,resultReading=false;const bridgeWaiters=new Map;
function bridgeCall(kind,payload={},timeout=35000){return new Promise((resolve,reject)=>{const requestId=uid(),timer=setTimeout(()=>{bridgeWaiters.delete(requestId);reject(Error('Chưa thấy extension. Cài Bridge 0.4.0 rồi tải lại trang Xưởng.'))},timeout);bridgeWaiters.set(requestId,{resolve,reject,timer});window.postMessage({source:'XN_STUDIO_V1',requestId,kind,...payload},location.origin)})}
window.addEventListener('message',e=>{if(e.source!==window||e.origin!==location.origin||e.data?.source!=='XN_EXTENSION_V1')return;if(e.data.notice==='result'){receiveResults();return}const waiting=bridgeWaiters.get(e.data.requestId);if(waiting){clearTimeout(waiting.timer);bridgeWaiters.delete(e.data.requestId);waiting.resolve(e.data.result)}});
const bridgeRender=render;render=function(){db.aiJobs??=[];if(view==='ai'){const prior=view;view='settings';bridgeRender();view=prior;$('#main').innerHTML=aiPage();$('#breadcrumb').textContent='Không gian làm việc / ChatGPT';document.title='ChatGPT | Xưởng Nội Dung';$('#nav a[href="#ai"]')?.classList.add('active');$('#nav a[href="#settings"]')?.classList.remove('active')}else bridgeRender();bridgeHeader()};
function bridgeHeader(){let b=$('#bridgeStatus');if(!b){b=document.createElement('button');b.id='bridgeStatus';$('header').append(b)}b.textContent=bridgeStatus.connected?'ChatGPT: Đã chọn tab':'Kết nối ChatGPT';b.onclick=()=>{location.hash='ai';refreshBridge()}}
function aiPage(){const jobs=(db.aiJobs||[]).slice().reverse();return heading('Kết nối ChatGPT','Viết truyện và tạo ảnh bằng tab ChatGPT của bạn. Không dùng API key.','<button id="bridgeRefresh">Kiểm tra kết nối</button>')+flowNotice('Sau khi extension điền yêu cầu vào ChatGPT, bạn kiểm tra rồi bấm Gửi. Chỉ nhận kết quả gắn đúng mã công việc. Giới hạn của gói ChatGPT vẫn áp dụng.')+`<section class="panel"><h2>${bridgeStatus.connected?'Đã chọn tab ChatGPT':'Chưa kết nối extension'}</h2><p class="help-text mt">${bridgeStatus.connected?esc(bridgeStatus.conversation?.title||'ChatGPT'):'Cài Xưởng ChatGPT Bridge 0.4.0, mở popup extension và chọn tab ChatGPT.'}</p><div class="actions"><a class="download-link" href="https://chatgpt.com/library?file_id=libfile_e8fca77d87348191b66d9b1a99e69441&amp;account_id=personal" target="_blank" rel="noopener noreferrer">Tải extension 0.4.0</a><a class="download-link" href="/downloads/Xuong_ChatGPT_Bridge_v0.4.0.zip" target="_blank" rel="noopener noreferrer" download="Xuong_ChatGPT_Bridge_v0.4.0.zip">Tải ZIP dự phòng</a><button id="bridgeHelp">Hướng dẫn cài</button><button id="bridgeReceive">Nhận lại kết quả</button><button id="bridgeCancel">Dừng đồng bộ</button></div><p class="help-text mt">${bridgeStatus.activeJob?'Đang chạy: '+esc(bridgeStatus.activeJob.state):'Không có công việc đang chạy.'}</p><p class="help-text mt">Nút tải mở trang tệp trong tab mới. Chọn Tải xuống tại đó. Cài extension bằng Chrome hoặc Edge trên máy tính.</p><div id="bridgeInstallHelp" hidden><ol><li>Bấm Tải extension 0.4.0 để mở trang tệp trong tab mới, rồi chọn Tải xuống. Nếu tab mới không mở, cho phép mở tab hoặc dùng Tải ZIP dự phòng. Giải nén ZIP thành một thư mục.</li><li>Chrome hoặc Edge: mở trang quản lý tiện ích, bật Chế độ nhà phát triển, chọn Tải tiện ích đã giải nén và chọn thư mục có manifest.json.</li><li>Tải lại Xưởng và tab ChatGPT. Mở popup extension, chọn đúng tab rồi bấm Kết nối.</li><li>Mở bài/chương hoặc yêu cầu ảnh trong Xưởng, bấm Viết/Tạo ảnh bằng ChatGPT.</li><li>Kiểm tra yêu cầu ở ChatGPT, bấm Gửi. Kết quả sẽ về Xưởng khi hoàn tất.</li></ol><p>Extension dành cho Chrome/Edge trên máy tính. Điện thoại hoặc Firefox vẫn dùng sao chép/dán thủ công. Xưởng và ChatGPT phải mở trong cùng trình duyệt, cùng profile.</p></div></section><section class="panel mt"><div class="panel-head"><h2>Công việc AI</h2><span class="muted">${jobs.length} công việc</span></div>${jobs.length?jobs.map(j=>`<div class="row"><div><strong>${esc(j.title)}</strong><small>${j.type==='image'?'Tạo ảnh':'Viết nội dung'} / ${dateText(j.createdAt)} / ${esc(jobState(j))}</small>${j.error?`<small class="error-text">${esc(j.error)}</small>`:''}</div><div class="actions">${j.status==='ready'&&j.type==='text'?`<button class="primary" data-aiapply="${j.id}">Đưa kết quả vào bài</button>`:''}${j.status==='stopped'?`<button data-airesume="${j.id}">Nhận kết quả đã dừng</button>`:''}${j.resultText?`<button data-aiview="${j.id}">Xem kết quả</button>`:''}<button data-aitarget="${j.id}">Mở ${j.type==='image'?'ảnh':'bài'}</button></div></div>`).join(''):empty('Chưa có công việc AI','Bắt đầu từ trình soạn bài hoặc tab Hình ảnh.')}</section>`}
function jobState(j){return ({queued:'Đang chuyển yêu cầu',waiting_send:'Chờ gửi trong ChatGPT',running:'Đang xử lý',ready:'Đã nhận, chờ áp dụng',applied:'Đã đồng bộ, chờ duyệt',error:'Lỗi',stopped:'Đã dừng'})[j.status]||j.status}
const aiOpenEditor=openEditor;openEditor=function(type,id='',defaults={}){aiOpenEditor(type,id,defaults);if(type==='content'&&$('#editor').open&&editType==='content')$('#fields').insertAdjacentHTML('beforeend','<div class="helper"><h3>Sản xuất bằng ChatGPT</h3><p>Lưu bài hiện tại rồi chuyển yêu cầu sang tab ChatGPT đã chọn. Kết quả được đưa về để bạn duyệt.</p><button type="button" id="aiWrite" class="primary">Viết bằng ChatGPT</button></div>')};
const aiOpenWorkflow=openWorkflow;openWorkflow=function(type,id='',defaults={}){aiOpenWorkflow(type,id,defaults);if(type==='asset')$('#workflowFields').insertAdjacentHTML('beforeend','<div class="helper"><h3>Tạo ảnh bằng ChatGPT</h3><p>Gửi prompt đã chuẩn bị. Ảnh nhận về luôn ở trạng thái Chưa duyệt.</p><button type="button" id="aiImage" class="primary">Tạo ảnh bằng ChatGPT</button></div>')};
function saveEditorForAI(type){const list=type==='text'?db.content:db.assets,before=new Set(list.map(x=>x.id)),existing=type==='text'?editId:wfId,dialog=type==='text'?$('#editor'):wfDialog;if(type==='text')$('#editForm').requestSubmit();else $('#workflowForm').requestSubmit();if(dialog.open)return null;const updated=type==='text'?db.content:db.assets;return existing?updated.find(x=>x.id===existing):updated.find(x=>!before.has(x.id))}
async function startAI(type){const button=type==='text'?$('#aiWrite'):$('#aiImage');if(button?.disabled)return;if(button)button.disabled=true;try{const check=await bridgeCall('XN_STATUS',{},4000);if(!check?.ok||!check.connected)throw Error('Mở popup extension và chọn tab ChatGPT trước.');bridgeStatus=check;const prompt=type==='text'?fullPrompt():(()=>{const d=wfValues();return d.globalStyle||d.scenePrompt?['Create exactly one standalone image.','Aspect ratio: '+d.ratio,'GLOBAL STYLE: '+d.globalStyle,'SCENE: '+d.scenePrompt,'No collage, no watermark. Follow the supplied facts.'].join('\n\n'):d.prompt})();if(!prompt.trim())throw Error('Cần câu lệnh trước khi gửi.');if(type==='text'&&!formValue().title.trim())throw Error('Nhập tiêu đề trước khi gửi.');const target=saveEditorForAI(type);if(!target)return;db.aiJobs??=[];const job={id:'xn_'+uid().replaceAll('-',''),type,targetId:target.id,title:target.title,createdAt:new Date().toISOString(),baseUpdatedAt:target.updatedAt||'',baseBody:target.body||'',status:'queued'};const previous=JSON.stringify(db);db.aiJobs.push(job);if(!save()){db=JSON.parse(previous);return}const textPrompt=type==='text'?prompt+'\n\nChỉ viết nội dung văn bản. Không tạo ảnh. Trả một JSON hợp lệ, không markdown: {"title":"tiêu đề","body":"toàn bộ nội dung bài hoặc chương","summary":"tóm tắt ngắn để nối chương sau"}.':prompt;const response=await bridgeCall('XN_START',{job:{id:job.id,type,prompt:textPrompt}});if(!response?.ok){job.status='error';job.error=response?.error||'Không gửi được yêu cầu';save();throw Error(job.error)}job.status='waiting_send';save();toast('Đã chuyển yêu cầu. Kiểm tra và bấm Gửi trong ChatGPT.');if(view==='ai')render();refreshBridge()}catch(e){toast(e.message)}finally{if(button)button.disabled=false}}
function parseStory(text){let raw=text.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');try{const data=JSON.parse(raw);if(data&&typeof data.body==='string'&&data.body.trim())return {body:data.body,title:typeof data.title==='string'?data.title:'',summary:typeof data.summary==='string'?data.summary:''}}catch{}return {body:raw,title:'',summary:''}}
function canAutoApply(j,c){return c&&['idea','draft'].includes(c.status)&&(c.updatedAt||'')===j.baseUpdatedAt&&(c.body||'')===j.baseBody}
function applyStory(j,c){const parsed=parseStory(j.resultText),now=new Date().toISOString();c.history=Array.isArray(c.history)?[...c.history]:[];c.history.push({at:now,title:c.title,body:c.body,status:c.status});c.history=c.history.slice(-30);c.body=parsed.body;c.summary=parsed.summary;c.status='review';c.scheduledAt='';c.publishedAt=null;c.updatedAt=now;j.status='applied';j.appliedAt=now}
async function importAIImage(j,result){const a=db.assets.find(x=>x.id===j.targetId);if(!a)throw Error('Ảnh đích đã bị xóa');if(!/^data:image\/(png|jpeg|webp);base64,/.test(result.image))throw Error('Ảnh nhận về không hợp lệ');const blob=await (await fetch(result.image)).blob(),bitmap=await createImageBitmap(blob),scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const key=uid();await putOriginal(key,new File([blob],'chatgpt-'+j.id+'.'+(blob.type==='image/png'?'png':blob.type==='image/webp'?'webp':'jpg'),{type:blob.type}));if(a.data){const newAsset={...a,id:uid(),title:a.title+' — kết quả ChatGPT',data:canvas.toDataURL('image/jpeg',.82),originalKey:key,approval:'draft',updatedAt:new Date().toISOString()};db.assets.push(newAsset);j.targetId=newAsset.id}else{a.data=canvas.toDataURL('image/jpeg',.82);a.originalKey=key;a.approval='draft';a.updatedAt=new Date().toISOString()}j.status='applied'}
async function receiveResults(){if(resultReading)return;resultReading=true;try{db.aiJobs??=[];const ids=db.aiJobs.map(j=>j.id),response=await bridgeCall('XN_GET_RESULTS',{jobIds:ids},5000);if(!response?.ok)return;for(const result of response.results||[]){const j=db.aiJobs.find(j=>j.id===result.jobId);if(!j||j.status==='stopped')continue;if(['applied','ready'].includes(j.status)){await bridgeCall('XN_ACK',{jobId:j.id,jobIds:ids});continue}const before=JSON.stringify(db);try{j.resultText=result.text||'';j.conversationUrl=result.conversationUrl;j.receivedAt=result.receivedAt;if(j.type==='image'){if(result.image)await importAIImage(j,result);else{j.status='error';j.error=result.imageError||'Không lấy được ảnh. Tải ảnh và nhập vào mục ảnh tương ứng.'}}else{const c=db.content.find(c=>c.id===j.targetId);if(canAutoApply(j,c)&&!($('#editor').open&&editType==='content'&&editId===c.id)){applyStory(j,c)}else j.status='ready'}if(!save()){db=JSON.parse(before);return}await bridgeCall('XN_ACK',{jobId:j.id,jobIds:ids});toast(j.type==='text'?'Đã nhận nội dung từ ChatGPT. Mở công việc để xem và duyệt.':j.status==='applied'?'Đã nhận ảnh từ ChatGPT, chờ duyệt.':j.error);if(view==='ai'||view==='images'||view==='content')render()}catch(e){db=JSON.parse(before);toast('Chưa lưu kết quả: '+e.message+' Kết quả vẫn giữ trong extension.')}}}catch{}finally{resultReading=false}}
async function refreshBridge(){if(bridgeChecking)return;bridgeChecking=true;try{const oldSignature=JSON.stringify([bridgeStatus.connected,bridgeStatus.activeJob?.id,bridgeStatus.activeJob?.state]);const r=await bridgeCall('XN_STATUS',{},3000);bridgeStatus=r?.ok?r:{connected:false};db.aiJobs??=[];const active=bridgeStatus.activeJob;if(active){const j=db.aiJobs.find(j=>j.id===active.id);if(j&&['waiting_send','queued','running'].includes(j.status)){j.status=active.state==='waiting_send'?'waiting_send':'running';j.progress=active.state;save()}}bridgeHeader();if(view==='ai'&&!$('#editor').open&&!wfDialog.open&&oldSignature!==JSON.stringify([bridgeStatus.connected,bridgeStatus.activeJob?.id,bridgeStatus.activeJob?.state]))render();if(r?.ok)receiveResults()}catch{const wasConnected=bridgeStatus.connected;bridgeStatus={connected:false};bridgeHeader();if(view==='ai'&&wasConnected)render()}finally{bridgeChecking=false}}
const resultDialog=document.createElement('dialog');resultDialog.innerHTML='<div class="dialog-head"><h2>Kết quả ChatGPT</h2><button id="closeAIResult" aria-label="Đóng kết quả">×</button></div><pre id="aiResultText" class="history-body"></pre>';document.body.append(resultDialog);$('#closeAIResult').onclick=()=>resultDialog.close();
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='aiWrite')startAI('text');if(b.id==='aiImage')startAI('image');if(b.id==='bridgeRefresh')refreshBridge();if(b.id==='bridgeReceive')receiveResults();if(b.id==='bridgeHelp')$('#bridgeInstallHelp').hidden=!$('#bridgeInstallHelp').hidden;if(b.id==='bridgeCancel'){try{const r=await bridgeCall('XN_CANCEL',{},5000);if(!r?.ok)throw Error(r?.error||'Không dừng được');for(const j of db.aiJobs||[])if(['queued','waiting_send','running'].includes(j.status))j.status='stopped';save();toast('Đã dừng đồng bộ. Nếu cần, bấm Dừng trong ChatGPT.');refreshBridge()}catch(e){toast(e.message)}}if(b.dataset.airesume){const j=db.aiJobs.find(j=>j.id===b.dataset.airesume);if(j){j.status='waiting_send';save();receiveResults();toast('Đã cho phép nhận kết quả đang giữ trong extension.')}}if(b.dataset.aiview){const j=db.aiJobs.find(j=>j.id===b.dataset.aiview);$('#aiResultText').textContent=j?.resultText||'';resultDialog.showModal()}if(b.dataset.aitarget){const j=db.aiJobs.find(j=>j.id===b.dataset.aitarget);if(j){if(j.type==='image')openWorkflow('asset',j.targetId);else openEditor('content',j.targetId)}}if(b.dataset.aiapply){const j=db.aiJobs.find(j=>j.id===b.dataset.aiapply),c=db.content.find(c=>c.id===j?.targetId);if(!c)return toast('Bài gốc đã bị xóa. Xem và sao chép kết quả để giữ lại.');if(!await uiConfirm('Đưa kết quả ChatGPT vào bài và chuyển sang Chờ duyệt? Nội dung cũ được giữ trong lịch sử; lịch đăng hiện tại sẽ được bỏ.'))return;const before=JSON.stringify(db);applyStory(j,c);if(!save()){db=JSON.parse(before);return}render();toast('Đã đưa vào bài, chờ bạn duyệt.')}});
const oldSettingsAI=settingsPage;settingsPage=function(){return oldSettingsAI()+`<section class="panel mt"><h2>ChatGPT Bridge</h2><p class="help-text mt">Chọn tab ChatGPT qua extension để viết nội dung và nhận ảnh, không dùng API key.</p><button data-go="ai">Mở kết nối ChatGPT</button></section>`};
window.addEventListener('focus',()=>{refreshBridge();receiveResults()});setInterval(refreshBridge,12000);setInterval(()=>{if(bridgeStatus.connected)receiveResults()},6000);view=navs[location.hash.slice(1)]?location.hash.slice(1):view;render();refreshBridge();
